import {createRoot} from 'react-dom/client';import {useState} from 'react';import IntakeQuestion from '../../../src/IntakeQuestion';import '../../../src/styles.css';import '../../../src/intake-pilot.css';
function Fixture(){const [revision,setRevision]=useState(0),[inquiry,setInquiry]=useState<{text:string}>();return <main className="rp-shell" style={{maxWidth:800,margin:'24px auto',padding:16}}><h1>Consulta sintética</h1><button onClick={()=>setRevision(x=>x+1)}>Cambiar reservas sintéticas</button><button onClick={()=>setInquiry({text:'Consulta nueva del artículo 117 de la Ley Aduanera.'})}>Cambiar artículo sintético</button><IntakeQuestion disabled={false} reservationRevision={revision} articleInquiry={inquiry} onPermit={async()=>{}} onSelect={async()=>{}}/></main>;}createRoot(document.getElementById('root')!).render(<Fixture/>);
